window.AKT.refaatLibrary = [{"kind":"book","title":{"ar":"دراكيولا","en":"Dracula"},"by":{"ar":"برام ستوكر","en":"Bram Stoker"},"who":"refaat","series":"mwt","issues":[1],"said":{"ar":"يستحضر رواية ستوكر الشهيرة في أول مغامراته، حين تقوده رحلته إلى أسطورة الكونت ومصاصي الدماء.","en":"He calls up Stoker's famous novel in his very first adventure, when his journey leads him into the Count's legend."},"src":["https://www.abjjad.com/book/2144567296/%D9%85%D8%B5%D8%A7%D8%B5-%D8%A7%D9%84%D8%AF%D9%85%D8%A7%D8%A1-%D9%88%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%B1%D8%AC%D9%84-%D8%A7%D9%84%D8%B0%D8%A6%D8%A8-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1/2144731136/quotes","https://ar.wikipedia.org/wiki/%D9%85%D8%A7_%D9%88%D8%B1%D8%A7%D8%A1_%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9_(%D8%B3%D9%84%D8%B3%D9%84%D8%A9)"]},{"kind":"author","title":{"ar":"إدجار آلان بو","en":"Edgar Allan Poe"},"by":null,"who":"refaat","series":"mwt","issues":[1,19],"said":{"ar":"يقول إنه تعلّم من قصص بو كيف تسير الحكاية دائمًا، ثم يجد نفسه في «أسطورة بو» حبيس قصصه — «قناع الموت الأحمر» و«القلب الواشي» و«الحفرة والبندول» و«القط الأسود» و«سقوط بيت أشر» و«ويليام ويلسون» و«ليجيا» — لا يخرج منها إلا بتغيير نهاياتها.","en":"He says Poe's stories taught him how such a tale always goes; in issue 19 he is trapped inside them — The Masque of the Red Death, The Tell-Tale Heart, The Pit and the Pendulum, The Black Cat, The Fall of the House of Usher, William Wilson, Ligeia — and escapes only by changing their endings."},"src":["https://www.abjjad.com/book/2144567296/%D9%85%D8%B5%D8%A7%D8%B5-%D8%A7%D9%84%D8%AF%D9%85%D8%A7%D8%A1-%D9%88%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%B1%D8%AC%D9%84-%D8%A7%D9%84%D8%B0%D8%A6%D8%A8-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1/2144731136/quotes","https://ar.wikipedia.org/wiki/%D8%A3%D8%B3%D8%B7%D9%88%D8%B1%D8%A9_%D8%A8%D9%88"]},{"kind":"poem","title":{"ar":"الكوميديا الإلهية (الجحيم)","en":"The Divine Comedy (Inferno)"},"by":{"ar":"دانتي أليجييري","en":"Dante Alighieri"},"who":"refaat","series":"mwt","issues":[19],"said":{"ar":"يفتتح عالم بو بالعبارة المنقوشة على باب الجحيم عند دانتي: اتركوا وراءكم كل أمل، ثم يعلن أن القارئ صار ضيفًا على بو.","en":"He opens Poe's world with Dante's inscription over the gate of Hell — abandon all hope — and tells the reader he is now Poe's guest."},"src":["https://www.abjjad.com/book/2170159905/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A8%D9%88-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-19/2170356513/quotes"]},{"kind":"music","title":{"ar":"أغنيات أم كلثوم","en":"Umm Kulthum's songs"},"by":{"ar":"أم كلثوم","en":"Umm Kulthum"},"who":"refaat","series":"mwt","issues":[27,28,31,65],"said":{"ar":"يرى أن أم كلثوم لا تُسمع إلا ليلًا على محطة يشوبها التشويش، ويحاول أن يشرحها لماجي فيقول إنها مزيج لا يفهمه إلا عربي، كتلاوة الشيخ محمد رفعت قبل الإفطار؛ وصوتها يأتيه من مذياع عتيق في ليالي الشتاء.","en":"He holds that Umm Kulthum is only heard at night, on a station with a little static; explaining her to Maggie he says she is a blend only an Arab understands, like Sheikh Mohamed Refaat's recitation before iftar; and her voice reaches him from an old radio on winter nights."},"src":["https://www.abjjad.com/book/2137948160/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D8%AE%D8%B1-%D8%A7%D9%84%D9%84%D9%8A%D9%84-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-28/2138112000/quotes/1","https://www.abjjad.com/book/2793406473/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%AA%D9%87%D8%A7-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-31/2794455049/quotes/1","https://www.goodreads.com/quotes/643219","https://www.goodreads.com/quotes/9500214"]},{"kind":"poem","title":{"ar":"قصائد إبراهيم ناجي","en":"Ibrahim Nagi's poems"},"by":{"ar":"إبراهيم ناجي","en":"Ibrahim Nagi"},"who":"refaat","series":"mwt","issues":[27],"said":{"ar":"حين يُسأل إن كان قد أحب، يقول إن العزلة تجعل المشاعر تتراكم، فتظهر سريعًا أغنيات أم كلثوم وقصائد ناجي والوردة الحمراء قبل أن تسأل نفسك إن كنت تحب حقًا.","en":"Asked whether he has fallen in love, he says that in a closed world feelings pile up, and Umm Kulthum's songs, Nagi's poems and the red rose arrive before you can ask if it is really love."},"src":["https://www.goodreads.com/quotes/643219"]},{"kind":"book","title":{"ar":"روميو وجولييت","en":"Romeo and Juliet"},"by":{"ar":"وليم شكسبير","en":"William Shakespeare"},"who":"refaat","series":"mwt","issues":[35],"said":{"ar":"يقول ساخرًا إن ما جرى لروميو وجولييت رومانسي فقط لمن يقرؤه في فراشه ليلًا، لا للعاشقين أنفسهما.","en":"He remarks dryly that what happened to Romeo and Juliet is romantic only to someone reading it in bed at night, not to the lovers themselves."},"src":["https://www.abjjad.com/book/2793406471/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%AF%D9%85%D8%A7%D8%A1-%D8%AF%D8%B1%D8%A7%D9%83%D9%8A%D9%88%D9%84%D8%A7-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-35/2794455047/quotes"]},{"kind":"film","title":{"ar":"توم وجيري","en":"Tom and Jerry"},"by":null,"who":"refaat","series":"mwt","issues":[35],"said":{"ar":"يتساءل إن كان منطق القط توم الذي لا يلتهم الفأر جيري أبدًا هو ما يمنع الحياة من أن تصير مملة كالجحيم.","en":"He wonders whether the logic of Tom the cat, who never actually eats Jerry, is what keeps life from becoming dull as hell."},"src":["https://www.abjjad.com/book/2793406471/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%AF%D9%85%D8%A7%D8%A1-%D8%AF%D8%B1%D8%A7%D9%83%D9%8A%D9%88%D9%84%D8%A7-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-35/2794455047/quotes"]},{"kind":"book","title":{"ar":"فرانكنشتاين","en":"Frankenstein"},"by":{"ar":"ماري شيلي","en":"Mary Shelley"},"who":"refaat","series":"mwt","issues":[41],"said":{"ar":"يعدّها خيالًا جامحًا أكثر من اللازم يتخيل إنسانًا يخلق الحياة، ويرى أنها إذا نُزع عنها الرعب رواية عن طفل يولد بلا أم، ولا تُفهم إلا في ضوء الثورة العلمية التي أنجبتها.","en":"He calls it an overly wild fantasy of man creating life, which, stripped of its horror, is about a child born without a mother — to be read against the scientific revolution that produced it."},"src":["https://www.abjjad.com/book/2793537545/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D9%81%D8%B1%D8%A7%D9%86%D9%83%D8%B4%D8%AA%D8%A7%D9%8A%D9%86-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-41/2794586121/quotes","https://ar.wikipedia.org/wiki/%D9%85%D8%A7_%D9%88%D8%B1%D8%A7%D8%A1_%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9_(%D8%B3%D9%84%D8%B3%D9%84%D8%A9)"]},{"kind":"book","title":{"ar":"العزيف (نيكرونوميكون)","en":"Al Azif (the Necronomicon)"},"by":{"ar":"هوارد فيليبس لافكرافت (المنسوب إلى عبد الله الحظرد)","en":"H. P. Lovecraft (ascribed to 'Abdul Alhazred')"},"who":"refaat","series":"mwt","issues":[65],"said":{"ar":"تدور «العلامات الدامية» حول أوراق هي ترجمات لكتاب العزيف؛ يزن رفعت الشواهد على وجوده دون أن يجزم بنفيه، لكنه يقطع بأن لافكرافت اختلق «عبد الله الحظرد»، ويمزح بأن الكتاب شفى رجلًا من «عقدة الخواجة» إلى الأبد.","en":"Issue 65 turns on pages that prove to be translations of Al Azif; Refaat weighs the evidence for the book without ruling it out, but is sure Lovecraft invented 'Abdul Alhazred' — and jokes that the book cured one man of his awe of foreigners for good."},"src":["https://ar.m.wikipedia.org/wiki/%D8%A3%D8%B3%D8%B7%D9%88%D8%B1%D8%A9_%D8%A7%D9%84%D8%B9%D9%84%D8%A7%D9%85%D8%A7%D8%AA_%D8%A7%D9%84%D8%AF%D8%A7%D9%85%D9%8A%D8%A9","https://www.abjjad.com/book/2793963523/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%B9%D9%84%D8%A7%D9%85%D8%A7%D8%AA-%D8%A7%D9%84%D8%AF%D8%A7%D9%85%D9%8A%D8%A9-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9/2795012099/quotes","https://www.goodreads.com/book/show/6045946"]},{"kind":"film","title":{"ar":"أفلام راي هاريهاوزن القديمة","en":"Ray Harryhausen's old films"},"by":{"ar":"راي هاريهاوزن","en":"Ray Harryhausen"},"who":"refaat","series":"mwt","issues":[65],"said":{"ar":"يشبّه حركة رجل متخشبة بديناصورات هاريهاوزن في أفلامه القديمة، حتى إن رؤيته ينهض تكاد تكون مؤثرة.","en":"He likens a man's stiff movements to the jerky dinosaurs of Harryhausen's old films, so that watching him stand up is almost touching."},"src":["https://www.abjjad.com/book/2793963523/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%B9%D9%84%D8%A7%D9%85%D8%A7%D8%AA-%D8%A7%D9%84%D8%AF%D8%A7%D9%85%D9%8A%D8%A9-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9/2795012099/quotes"]},{"kind":"music","title":{"ar":"كارمينا بورانا","en":"Carmina Burana"},"by":{"ar":"كارل أورف","en":"Carl Orff"},"who":"refaat","series":"mwt","issues":[74],"said":{"ar":"تقوم «أغنية الموت» على القصة الخفية وراء أوبرا أورف: شريط يصل إلى ركاب طائرة رفعت فيها، يحمل أوبرا تشبه كارمينا بورانا وهي في الوقت نفسه نداء خفي.","en":"Issue 74 is built on the hidden story behind Orff's work: a tape reaches the passengers of Refaat's flight carrying an opera like Carmina Burana that is also a secret summons."},"src":["https://ar.wikipedia.org/wiki/%D8%A3%D8%B3%D8%B7%D9%88%D8%B1%D8%A9_%D8%A3%D8%BA%D9%86%D9%8A%D8%A9_%D8%A7%D9%84%D9%85%D9%88%D8%AA","https://3rabica.org/%D9%85%D8%A7_%D9%88%D8%B1%D8%A7%D8%A1_%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9_(%D8%B3%D9%84%D8%B3%D9%84%D8%A9)"]},{"kind":"book","title":{"ar":"كل شيء هادئ في الجبهة الغربية","en":"All Quiet on the Western Front"},"by":{"ar":"إريش ماريا ريمارك","en":"Erich Maria Remarque"},"who":"refaat","series":"mwt","issues":[24],"said":{"ar":"يحوّر عنوان ريمارك إلى «كل شيء هادئ في الجبهة الغريبة» ليصف تقريرًا اعتبر موت رجل واحد خسارة لا تستحق الذكر.","en":"He twists Remarque's title into 'all quiet on the strange front' to describe a report that counted one man's death as no loss worth mentioning."},"src":["https://www.abjjad.com/book/15445985/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%8A%D8%AC%D9%88%D8%B1-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-24/24749332/quotes"]},{"kind":"film","title":{"ar":"أفلام لويس بونويل","en":"Luis Buñuel's films"},"by":{"ar":"لويس بونويل","en":"Luis Buñuel"},"who":"refaat","series":"mwt","issues":[66],"said":{"ar":"يصف بونويل بالمخرج الإسباني السريالي المجنون الذي كان يعشق الحشرات ويضعها في كل أفلامه.","en":"He describes Buñuel as the mad Spanish surrealist who adored insects and put them in all his films."},"src":["https://abjjad.com/book/2793996292/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%B1%D8%AC%D8%A7%D9%84-%D8%A7%D9%84%D8%B0%D9%8A%D9%86-%D9%84%D9%85-%D9%8A%D8%B9%D9%88%D8%AF%D9%88%D8%A7-%D9%83%D8%B0%D9%84%D9%83-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88/2795044868/quotes"]},{"kind":"book","title":{"ar":"ما كتبه كالميه عن مصاصي الدماء","en":"Calmet on vampires"},"by":{"ar":"أوجستان كالميه","en":"Augustin Calmet"},"who":"refaat","series":"mwt","issues":[80],"said":{"ar":"يذكر أن باحثًا فرنسيًا محترمًا هو كالميه كتب عن مصاصي الدماء عام 1746 وقال بوجودهم.","en":"He notes that a respected French scholar, Calmet, wrote on vampires in 1746 and argued that they exist."},"src":["https://abjjad.com/book/2196996335/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%A7%D8%B3%D8%A7%D8%B7%D9%8A%D8%B1-%D8%A7%D9%84%D8%AC%D8%B2%D8%A1-%D8%A7%D9%84%D8%A7%D9%88%D9%84-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7/2197258481/quotes"]},{"kind":"poem","title":{"ar":"الوقوف عند الغابة في مساء مثلج","en":"Stopping by Woods on a Snowy Evening"},"by":{"ar":"روبرت فروست","en":"Robert Frost"},"who":"refaat","series":"mwt","issues":[80],"said":{"ar":"في العدد الأخير يردد أبيات فروست: الغابة جميلة مظلمة عميقة، لكن عليه وعودًا يفي بها وأميالًا يقطعها قبل أن ينام.","en":"In the last issue he repeats Frost's lines: the woods are lovely, dark and deep, but he has promises to keep, and miles to go before he sleeps."},"src":["https://abjjad.com/book/2196996335/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%A7%D8%B3%D8%A7%D8%B7%D9%8A%D8%B1-%D8%A7%D9%84%D8%AC%D8%B2%D8%A1-%D8%A7%D9%84%D8%A7%D9%88%D9%84-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7/2197258481/quotes"]},{"kind":"poem","title":{"ar":"«فعاش الفسيل ومات الرجل»","en":"\"The sapling lived, and the man died\""},"by":{"ar":"منسوب إلى سيبويه","en":"ascribed to Sibawayh"},"who":"refaat","series":"mwt","issues":[80],"said":{"ar":"يستشهد ببيت عن رجل يؤمّل أن يعيش ليجني ثمار ما غرس، فيعيش الفسيل ويموت هو — وهو يكتب عدده الأخير.","en":"He quotes a verse about a man who hoped to live to enjoy the palms he planted — the sapling lived and the man died — as he writes his own last issue."},"src":["https://abjjad.com/book/2196996335/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%A7%D8%B3%D8%A7%D8%B7%D9%8A%D8%B1-%D8%A7%D9%84%D8%AC%D8%B2%D8%A1-%D8%A7%D9%84%D8%A7%D9%88%D9%84-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7/2197258481/quotes"]},{"kind":"poem","title":{"ar":"بطاقة هوية","en":"Identity Card"},"by":{"ar":"محمود درويش","en":"Mahmoud Darwish"},"who":"alaa","series":"safari","issues":[32],"said":{"ar":"يستعير علاء كلمات درويش: لا يكره الناس ولا يسطو على أحد، لكنه إذا جاع أكل لحم من اغتصبه — فاحذروا جوعه وغضبه.","en":"Alaa borrows Darwish's words: he hates no one and robs no one, but if he goes hungry he will eat the flesh of the one who wronged him — so beware his hunger and his anger."},"src":["https://www.abjjad.com/book/2800582661/%D9%84%D9%85%D8%A7%D8%B0%D8%A7-%D8%AC%D9%86%D8%AA-%D8%A7%D9%84%D8%A7%D8%A8%D9%82%D8%A7%D8%B1-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D8%B3%D8%A7%D9%81%D8%A7%D8%B1%D9%8A-32/2801631237/quotes"]},{"kind":"author","title":{"ar":"ألبرت شفايتزر","en":"Albert Schweitzer"},"by":null,"who":"alaa","series":"safari","issues":[1],"said":{"ar":"في أول أعداد سافاري يذكر علاء شفايتزر، الطبيب والفيلسوف العظيم الذي اشتهر في أرجاء إفريقيا، وهو يدخل عالم الطب في القارة.","en":"In Safari's first issue Alaa invokes Schweitzer, the great doctor-philosopher famous across Africa, as he steps into medicine on the continent."},"src":["https://www.abjjad.com/book/2798059521/%D8%A7%D9%84%D9%88%D8%A8%D8%A7%D8%A1-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D8%B3%D8%A7%D9%81%D8%A7%D8%B1%D9%8A-1/2799108097/quotes"]},{"kind":"author","title":{"ar":"أحمد رجب","en":"Ahmed Ragab"},"by":null,"who":"alaa","series":"safari","issues":[7],"said":{"ar":"يستشهد علاء بكلمة «الساخر العظيم» أحمد رجب في السخرية من كلام العشاق.","en":"Alaa quotes 'the great satirist' Ahmed Ragab poking fun at the way lovers talk."},"src":["https://www.abjjad.com/book/2797993985/%D8%A7%D9%84%D8%A7%D9%86-%D8%AA%D8%B1%D8%A7%D9%87-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D8%B3%D8%A7%D9%81%D8%A7%D8%B1%D9%8A-7/2799042561/quotes"]}];
